mapper.update:

UPDATE account_state SET account_state=#{deregisteredState},desired_login_state=2,login_state=2,state_source='CREATOR_DELETED',
  offline_since=COALESCE(offline_since,#{now}),invalidated_at=#{now},updated_at=#{now}
WHERE tenant_id=#{tenantId} AND account_id=#{accountId}

UPDATE pull_task_group_account SET released_at=#{now},availability_status=4,
  unavailable_reason_code='CREATOR_ACCOUNT_DELETED',updated_at=#{now}
WHERE tenant_id=#{binding.tenantId} AND task_id=#{binding.taskId}
  AND group_execution_id=#{binding.executionId} AND account_id=#{binding.accountId} AND role_type=4
  AND released_at IS NULL
